files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #533483;
  --win: #4ecca3;
  --lose: #e94560;
  --draw: #f0c040;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-board {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
  color: var(--primary);
  letter-spacing: 1px;
}

.scoreboard {
  display: flex;
  justify-content: space-around;
  margin-bottom: 24px;
  gap: 16px;
}

.score {
  background: var(--secondary);
  border-radius: 12px;
  padding: 12px 24px;
  flex: 1;
}

.label {
  display: block;
  font-size: 0.875rem;
  opacity: 0.8;
  margin-bottom: 4px;
}

.score-value {
  font-size: 1.75rem;
  font-weight: bold;
}

.choices-display {
  display: flex;
  justify-content: space-around;
  margin-bottom: 20px;
  gap: 16px;
}

.choice-box {
  background: var(--secondary);
  border-radius: 12px;
  padding: 16px;
  flex: 1;
}

.choice-label {
  display: block;
  font-size: 0.875rem;
  opacity: 0.8;
  margin-bottom: 8px;
}

.choice-icon {
  font-size: 2.5rem;
  line-height: 1;
}

.result {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 24px;
  min-height: 2em;
  padding: 8px;
  border-radius: 8px;
  background: var(--secondary);
}

.result.win {
  color: var(--win);
}

.result.lose {
  color: var(--lose);
}

.result.draw {
  color: var(--draw);
}

.controls {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

.choice-btn {
  flex: 1;
  min-width: 100px;
  padding: 14px 8px;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid transparent;
  border-radius: 10px;
  background: var(--accent);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
}

.choice-btn:hover {
  background: var(--primary);
}

.choice-btn:focus-visible {
  outline: none;
  border-color: var(--text);
  box-shadow: 0 0 0 3px var(--secondary);
}

.choice-btn:active {
  transform: scale(0.95);
}

.reset-btn {
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var(--primary);
  border-radius: 10px;
  background: transparent;
  color: var(--primary);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  width: 100%;
}

.reset-btn:hover {
  background: var(--primary);
  color: var(--text);
}

.reset-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--text);
}

.reset-btn:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .game-board {
    padding: 16px;
  }
  .choice-btn {
    min-width: 80px;
    font-size: 0.9rem;
    padding: 12px 4px;
  }
  .choice-icon {
    font-size: 2rem;
  }
}

const choices = ['rock', 'paper', 'scissors'];
const icons = { rock: '✊', paper: '✋', scissors: '✌️' };

let playerScore = 0;
let computerScore = 0;

const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const playerChoiceEl = document.getElementById('player-choice');
const computerChoiceEl = document.getElementById('computer-choice');
const resultEl = document.getElementById('result');

function getComputerChoice() {
  return choices[Math.floor(Math.random() * 3)];
}

function getResult(player, computer) {
  if (player === computer) return 'draw';
  if (
    (player === 'rock' && computer === 'scissors') ||
    (player === 'paper' && computer === 'rock') ||
    (player === 'scissors' && computer === 'paper')
  ) return 'win';
  return 'lose';
}

function updateDisplay(playerChoice, computerChoice, result) {
  playerChoiceEl.textContent = icons[playerChoice];
  computerChoiceEl.textContent = icons[computerChoice];

  resultEl.classList.remove('win', 'lose', 'draw');
  if (result === 'win') {
    resultEl.textContent = 'You win this round!';
    resultEl.classList.add('win');
  } else if (result === 'lose') {
    resultEl.textContent = 'Computer wins this round!';
    resultEl.classList.add('lose');
  } else {
    resultEl.textContent = "It's a draw!";
    resultEl.classList.add('draw');
  }
}

function playRound(playerChoice) {
  const computerChoice = getComputerChoice();
  const result = getResult(playerChoice, computerChoice);

  if (result === 'win') playerScore++;
  else if (result === 'lose') computerScore++;

  playerScoreEl.textContent = playerScore;
  computerScoreEl.textContent = computerScore;
  updateDisplay(playerChoice, computerChoice, result);
}

function resetGame() {
  playerScore = 0;
  computerScore = 0;
  playerScoreEl.textContent = '0';
  computerScoreEl.textContent = '0';
  playerChoiceEl.textContent = '❔';
  computerChoiceEl.textContent = '❔';
  resultEl.textContent = 'Choose your move!';
  resultEl.classList.remove('win', 'lose', 'draw');
}

choices.forEach(choice => {
  document.getElementById(choice).addEventListener('click', () => playRound(choice));
});

document.getElementById('reset').addEventListener('click', resetGame);
